for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"\nPair {i}: '{inp}' -> '{outp}'")
    if len(inp) <= len(outp):
        for j in range(len(inp)):
            if j < len(outp):
                print(f"  Position {j}: '{inp[j]}' -> '{outp[j]}'")
        if len(outp) > len(inp):
            print(f"  Extra chars in output: '{outp[len(inp):]}'")
    else:
        print(f"  Output is shorter than input")

